BEGIN;
CREATE SCHEMA IF NOT EXISTS retail_mess;
SET LOCAL search_path TO retail_mess;
DROP TABLE IF EXISTS wide_sales CASCADE;
CREATE TABLE wide_sales (
  row_id int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  order_no text,
  order_id text,
  customer_email text,
  customer_name text,
  delivery_city text,
  delivery_region text,
  delivery_country text,
  product_sku text,
  product_name text,
  product_category text,
  product_category_description text,
  quantity text,
  unit_price text,
  line_amount text,
  currency text,
  order_date text,
  order_status text,
  payment_method text,
  payment_id text,
  payment_amount text,
  sales_channel text
);
COMMIT;